import pytest

from minisheet.refs import Ref, parse_range, parse_ref, to_a1


def test_basic():
    assert parse_ref("B12") == Ref(1, 11, False, False)


def test_abs_lower():
    assert parse_ref("$zz$9999") == Ref(701, 9998, True, True)


def test_range_normalized():
    assert parse_range("$C3:A$1") == (Ref(0, 0, False, True), Ref(2, 2, True, False))


def test_range_single():
    assert parse_range("A1:A1") == (Ref(0, 0), Ref(0, 0))


def test_range_tie_first_corner():
    a, b = parse_range("$A1:A$2")
    assert a == Ref(0, 0, True, False) and b == Ref(0, 1, True, True)


def test_to_a1():
    assert to_a1(Ref(26, 0, True, False)) == "$AA1"
    assert to_a1(Ref(0, 0)) == "A1"
    assert to_a1(Ref(701, 9998, True, True)) == "$ZZ$9999"


@pytest.mark.parametrize("s", ["A0", "AAA1", "A01", "A10000", "", "A", "1", "A1 ", "A1\n", "$$A1", "A$"])
def test_bad_refs(s):
    with pytest.raises(ValueError):
        parse_ref(s)


def test_a01_rejected():
    with pytest.raises(ValueError):
        parse_ref("A01")


def test_range_bare_cell():
    with pytest.raises(ValueError):
        parse_range("A1")


@pytest.mark.parametrize("s", ["A1:", ":A1", "A1:B2:C3", "A1: B2"])
def test_bad_ranges(s):
    with pytest.raises(ValueError):
        parse_range(s)


@pytest.mark.parametrize("r", [Ref(702, 0), Ref(-1, 0), Ref(0, -1), Ref(0, 9999)])
def test_to_a1_out_of_range(r):
    with pytest.raises(ValueError):
        to_a1(r)
