s=s[:i]+'''_REF_RE = re.compile(r"(\\$?)([A-Za-z]{1,2})(\\$?)([1-9][0-9]{0,3})")


def parse_ref(s: str) -> Ref:
    m = _REF_RE.fullmatch(s)
    if not m:
        raise ValueError(f"invalid reference: {s!r}")
    letters = m.group(2).upper()
    col = 0
    for ch in letters:
        col = col * 26 + (ord(ch) - 64)
    col -= 1
    return Ref(col, int(m.group(4)) - 1, bool(m.group(1)), bool(m.group(3)))


def parse_range(s: str) -> tuple[Ref, Ref]:
    parts = s.split(":")
    if len(parts) != 2:
        raise ValueError(f"invalid range: {s!r}")
    a, b = parse_ref(parts[0]), parse_ref(parts[1])
    c_lo, c_hi = (a, b) if a.col <= b.col else (b, a)
    r_lo, r_hi = (a, b) if a.row <= b.row else (b, a)
    return (
        Ref(c_lo.col, r_lo.row, c_lo.abs_col, r_lo.abs_row),
        Ref(c_hi.col, r_hi.row, c_hi.abs_col, r_hi.abs_row),
    )


def to_a1(ref: Ref) -> str:
    if not (0 <= ref.col <= 701 and 0 <= ref.row <= 9998):
        raise ValueError(f"reference out of range: {ref!r}")
    if ref.col < 26:
        letters = chr(65 + ref.col)
    else:
        letters = chr(65 + ref.col // 26 - 1) + chr(65 + ref.col % 26)
    return f"{'$' if ref.abs_col else ''}{letters}{'$' if ref.abs_row else ''}{ref.row + 1}"
'''
s=s.replace("from dataclasses import dataclass","import re\nfrom dataclasses import dataclass")
open(p,'w').write(s)
